#![allow(unused_mut, non_snake_case, dead_code, clippy::needless_return, clippy::too_many_arguments)]
// Generated by Spiral portable Rust backend.
fn workspace_members_from_manifest(source: &str) -> Result<BTreeSet<String>, String> {
    let parsed = eoie_bundle_workspace_members_parse(source);
    if parsed.is_empty() { return Err("workspace members mapping missing, malformed, empty, or duplicate".to_owned()); }
    Ok(parsed.lines().map(str::to_owned).collect())
}


