#[derive(Default)]
struct BundleReport { errors: Vec<String>, crate_lines: Vec<(String, usize)>, public_bins: usize, state_files: usize, source_packages: usize, cargo_crates: usize, spiral_only_packages: usize }

fn arg<'a>(args: &'a [String], index: usize, name: &str) -> Result<&'a str, String> { args.get(index).map(String::as_str).ok_or_else(|| format!("missing argument: {name}")) }
fn parsed_max_bytes(value: &str) -> Result<u64, String> { if eoie_state_receipt_u64_decimal_valid(value) != 1 { return Err("max-bytes must be an unsigned integer".to_owned()); } Ok(eoie_state_receipt_u64_decimal_value(value)) }

fn rollback_rehydrate_destination(destination: &Path) -> Result<(), String> {
    if !rooted_entry_exists(destination)? { return Ok(()); }
    let parent = destination.parent().ok_or_else(|| format!("rehydration destination has no parent: {}", destination.display()))?;
    rooted_remove_tree_within(parent, destination).map(|_| ())
}

fn remove_bundle_output(output: &Path) -> Result<(), String> {
    if !rooted_entry_exists(output)? { return Ok(()); }
    rooted_remove_regular(output)
}

fn walk_crate(path: &Path, lines: &mut usize, report: &mut BundleReport) -> Result<(), String> {
    for name in rooted_list_names(path)? {
        let child = path.join(&name);
        if rooted_list_names(&child).is_ok() {
            if name == BUNDLE_ROOT_ENTRIES[2] { report.errors.push(format!("nested src is forbidden: {}", child.display())); }
            walk_crate(&child, lines, report)?;
        } else {
            let source = read_regular_text_limited(&child, usize::MAX)?;
            if name == BUNDLE_CRATE_FORBIDDEN_FILE { report.errors.push(format!("lib.rs is forbidden: {}", child.display())); }
            let source_file = child.extension().and_then(|value| value.to_str()).is_some_and(|extension| BUNDLE_SOURCE_EXTENSIONS.contains(&extension));
            if !source_file && !BUNDLE_CRATE_ALLOWED_FILES.contains(&name.as_str()) { report.errors.push(format!("unexpected crate file: {}", child.display())); }
            if source_file { *lines += source.lines().count(); }
        }
    }
    Ok(())
}

const BUNDLE_ROOT_ENTRIES: [&str; 4] = ["eoie", "evidence", "src", "state"];
const BUNDLE_EOIE_AGILE_PATH: &str = "state/agile.spi";
const BUNDLE_PROFILE_SIGNATURE: [&str; 4] = ["eoie", "state/package.spiproj", "state/core.spi", "src/Cargo.toml"];

fn bundle_profile_signature(root: &Path) -> i32 {
    let bootstrap_mask = i32::from(rooted_open_regular_read(&root.join(BUNDLE_PROFILE_SIGNATURE[0])).is_ok()) | (i32::from(rooted_open_regular_read(&root.join(BUNDLE_PROFILE_SIGNATURE[1])).is_ok()) << 1);
    let model_mask = i32::from(rooted_open_regular_read(&root.join(BUNDLE_PROFILE_SIGNATURE[2])).is_ok()) | (i32::from(rooted_open_regular_read(&root.join(BUNDLE_PROFILE_SIGNATURE[3])).is_ok()) << 1);
    eoie_bundle_profile_signature_binding(bootstrap_mask, model_mask)
}

fn resolve_bundle_profile_code(requested: Option<&str>, signature: i32) -> Result<i32, String> {
    let requested_code = match requested.unwrap_or("auto") {
        "auto" => 0,
        "generic" => 1,
        "eoie" => 2,
        other => return Err(format!("unknown bundle profile: {other}; expected auto, generic or eoie")),
    };
    let resolved = eoie_bundle_profile_resolve_binding(requested_code, signature);
    if resolved == 1 || resolved == 2 { Ok(resolved) } else { Err("typed bundle profile resolution rejected".to_owned()) }
}

fn resolve_bundle_profile(requested: Option<&str>, root: &Path) -> Result<i32, String> { resolve_bundle_profile_code(requested, bundle_profile_signature(root)) }

fn resolve_bundle_archive_profile(requested: Option<&str>, archive: &Path) -> Result<i32, String> {
    let entries = zip_entries(archive)?;
    let bootstrap_mask = i32::from(entries.iter().any(|entry| entry == BUNDLE_PROFILE_SIGNATURE[0])) | (i32::from(entries.iter().any(|entry| entry == BUNDLE_PROFILE_SIGNATURE[1])) << 1);
    let model_mask = i32::from(entries.iter().any(|entry| entry == BUNDLE_PROFILE_SIGNATURE[2])) | (i32::from(entries.iter().any(|entry| entry == BUNDLE_PROFILE_SIGNATURE[3])) << 1);
    resolve_bundle_profile_code(requested, eoie_bundle_profile_signature_binding(bootstrap_mask, model_mask))
}

const BUNDLE_CRATE_ALLOWED_FILES: [&str; 2] = ["Cargo.toml", "package.spiproj"];
const BUNDLE_CRATE_FORBIDDEN_FILE: &str = "lib.rs";
const BUNDLE_SOURCE_EXTENSIONS: [&str; 2] = ["rs", "spi"];
const BUNDLE_SOURCE_ROOT_FILES: [&str; 4] = ["Cargo.toml", "Cargo.lock", "package.spiproj", "rustfmt.toml"];
const BUNDLE_SOURCE_REQUIRED_FILES: [&str; 2] = ["Cargo.toml", "package.spiproj"];
const BUNDLE_STATE_REQUIRED_FILES: [&str; 3] = ["package.spiproj", "core.spi", "agile.spi"];
const BUNDLE_SOURCE_SPECIAL_DIRECTORIES: [&str; 2] = [".cargo", "vendor"];
const BUNDLE_EVIDENCE_PATHS: [&str; 2] = ["coverage", "current.lcov"];
const BUNDLE_STATE_WITNESS_FILES: [&str; 3] = ["coverage.spi", "consolidation_fixtures.spi", "dogfood_exit.spi"];
const BUNDLE_CARGO_CONFIG_FILE: &str = "config.toml";
const BUNDLE_VENDOR_CHECKSUM_FILE: &str = ".cargo-checksum.json";
const BUNDLE_ARCHIVE_DIRECTORY_ROOTS: [&str; 3] = ["evidence/", "src/", "state/"];
const BUNDLE_ARCHIVE_MAX_BYTES: u64 = 30_000_000;
const BUNDLE_EXTRACT_MAX_BYTES: u64 = 268_435_456;
const BUNDLE_CRATE_LINE_LIMIT: usize = 1000;
const BUNDLE_PUBLIC_BINARY_COUNT: usize = 1;

fn check_generic_bundle(root: &Path) -> Result<BundleReport, String> {
    let mut report = BundleReport::default();
    if rooted_list_names(root).is_err() {
        report.errors.push(format!("generic bundle root is not a directory: {}", root.display()));
        return Ok(report);
    }
    let manifest = collect_bundle_manifest(root)?;
    if manifest.is_empty() { report.errors.push("generic bundle root is empty".to_owned()); }
    Ok(report)
}

fn check_bundle(root: &Path) -> Result<BundleReport, String> {
    let mut report = BundleReport::default();
    if let Err(error) = owner_growth_all_owner_check(root) { report.errors.push(error); }
    if let Err(error) = active_rating_receipt_check(root) { report.errors.push(error); }
    if let Err(error) = validate_runtime_filenames(root) { report.errors.push(error); }
    let roots: BTreeSet<String> = rooted_list_names(root)?.into_iter().collect();
    let expected: BTreeSet<String> = BUNDLE_ROOT_ENTRIES.into_iter().map(str::to_owned).collect();
    for unexpected in roots.difference(&expected) { report.errors.push(format!("unexpected bundle root entry: {unexpected}")); }
    for missing in expected.difference(&roots) { report.errors.push(format!("missing bundle root entry: {missing}")); }
    if eoie_bundle_root_binding(i32::try_from(BUNDLE_ROOT_ENTRIES.len()).unwrap_or(i32::MAX), i32::try_from(roots.len()).unwrap_or(i32::MAX)) != 1 { report.errors.push(format!("typed bundle root mismatch: observed {}", roots.len())); }
    let state = root.join(BUNDLE_ROOT_ENTRIES[3]);
    let evidence = root.join(BUNDLE_ROOT_ENTRIES[1]);
    if rooted_list_names(&evidence).is_err() {
        report.errors.push("missing evidence root".to_owned());
    } else {
        if let Err(error) = check_evidence_tree(root) { report.errors.push(format!("evidence currentness: {error}")); }
        if let Err(error) = semantic_evidence_domain::verify_closeout_registry(root, semantic_evidence_domain::observed_migration_from_state(root)?) { report.errors.push(format!("semantic closeout: {error}")); }
        if let Err(error) = cold_proof_domain::verify_formal_authority(root) { report.errors.push(format!("ColdProofV4: {error}")); }
        for name in rooted_list_names(&evidence)? {
            let path = evidence.join(name);
            if rooted_list_names(&path).is_err() { report.errors.push(format!("unexpected evidence entry: {}", path.display())); }
        }
        let coverage_dir = evidence.join(BUNDLE_EVIDENCE_PATHS[0]);
        if rooted_list_names(&coverage_dir).is_err() {
            report.errors.push("missing evidence/coverage directory".to_owned());
        } else {
            for name in rooted_list_names(&coverage_dir)? {
                let path = coverage_dir.join(name);
                if read_regular_text_limited(&path, usize::MAX).is_err() { report.errors.push(format!("unexpected coverage evidence entry: {}", path.display())); }
            }
        }
        let coverage_source = read_regular_text_limited(&state.join(BUNDLE_STATE_WITNESS_FILES[0]), usize::MAX)?;
        let checkpoint_kind = eoie_state_receipt_coverage_checkpoint_kind(&coverage_source);
        if checkpoint_kind == 0 { report.errors.push("coverage checkpoint state is absent".to_owned()); }
        let declared_durable = i32::from(checkpoint_kind == 2);
        let checkpoint = coverage_dir.join(BUNDLE_EVIDENCE_PATHS[1]);
        let mut evidence_code = 0i32;
        if rooted_open_regular_read(&checkpoint).is_ok() {
            evidence_code = 1;
            if checkpoint_kind == 2 {
                let expected_sha = eoie_state_receipt_coverage_checkpoint_sha(&coverage_source);
                if expected_sha.is_empty() {
                    report.errors.push("coverage durable checkpoint sha is missing".to_owned());
                } else {
                    match inspection_file_sha256(&checkpoint) {
                        Ok(observed_sha) if observed_sha == expected_sha.as_ref() => evidence_code = 2,
                        Ok(observed_sha) => report.errors.push(format!("coverage checkpoint sha mismatch: expected={expected_sha} observed={observed_sha}")),
                        Err(error) => report.errors.push(format!("coverage checkpoint hash failed: {error}")),
                    }
                }
            }
        }
        if eoie_bundle_coverage_checkpoint_binding(declared_durable, evidence_code) != 1 {
            report.errors.push(format!("coverage checkpoint durability rejected: declared_durable={declared_durable} evidence_code={evidence_code}"));
        }
    }
    if let Ok(state_names) = rooted_list_names(&state) {
        report.state_files = state_names.len();
        for required in BUNDLE_STATE_REQUIRED_FILES { if !state_names.iter().any(|name| name == required) { report.errors.push(format!("missing state/{required}")); } } let fixture_path = state.join(BUNDLE_STATE_WITNESS_FILES[1]); if state_names.iter().any(|name| name == BUNDLE_STATE_WITNESS_FILES[1]) || state_names.iter().any(|name| name == BUNDLE_STATE_WITNESS_FILES[2]) { if !state_names.iter().any(|name| name == BUNDLE_STATE_WITNESS_FILES[1]) || !state_names.iter().any(|name| name == BUNDLE_STATE_WITNESS_FILES[2]) { report.errors.push("recovered capability fixture ledger and dogfood gate must coexist".to_owned()); } else { let ledger = read_regular_text_limited(&fixture_path, usize::MAX)?; let fixture_count = eoie_state_receipt_recovered_fixture_record_count_or_max(&ledger); if fixture_count == u64::MAX { report.errors.push("invalid settled fixture ledger".to_owned()); } else { let fixture_paths = eoie_state_receipt_recovered_fixture_paths(&ledger); for relative in fixture_paths.lines() { let path = root.join(relative); if !rooted_open_regular_read(&path).is_ok() { report.errors.push(format!("missing settled fixture evidence: {}", path.display())); } } let declared_count = eoie_state_receipt_recovered_topology_count_or_max(&ledger); let dogfood = read_regular_text_limited(&state.join(BUNDLE_STATE_WITNESS_FILES[2]), usize::MAX)?; let settled_count = eoie_state_receipt_recovered_topology_count_or_max(&dogfood); if fixture_count != declared_count || declared_count != settled_count { report.errors.push(format!("recovered capability fixture mismatch: records={fixture_count} declared={declared_count} dogfood={settled_count}")); } } } }
        for name in state_names {
            let path = state.join(&name);
            if rooted_list_names(&path).is_ok() || (name != BUNDLE_STATE_REQUIRED_FILES[0] && path.extension().and_then(|value| value.to_str()) != Some(BUNDLE_SOURCE_EXTENSIONS[1])) { report.errors.push(format!("state must be flat Spiral: {}", path.display())); }
            else { let _ = read_regular_text_limited(&path, usize::MAX)?; }
        }
    }
    let src = root.join(BUNDLE_ROOT_ENTRIES[2]);
    if let Ok(src_names) = rooted_list_names(&src) {
        let mut physical_cargo_members = BTreeSet::new();
        for required in BUNDLE_SOURCE_REQUIRED_FILES { if !src_names.iter().any(|name| name == required) { report.errors.push(format!("missing src/{required}")); } }
        for source_name in src_names {
            let path = src.join(&source_name);
            if rooted_list_names(&path).is_err() {
                let _ = read_regular_text_limited(&path, usize::MAX)?;
                if !BUNDLE_SOURCE_ROOT_FILES.contains(&source_name.as_str()) { report.errors.push(format!("source root file is forbidden: {}", path.display())); }
                continue;
            }
            if source_name == BUNDLE_SOURCE_SPECIAL_DIRECTORIES[0] { if read_regular_text_limited(&path.join(BUNDLE_CARGO_CONFIG_FILE), usize::MAX).is_err() { report.errors.push("missing or invalid src/.cargo/config.toml".to_owned()); } continue; }
            if source_name == BUNDLE_SOURCE_SPECIAL_DIRECTORIES[1] {
                for vendor_name in rooted_list_names(&path)? {
                    let vendor_path = path.join(&vendor_name);
                    let Ok(vendor_names) = rooted_list_names(&vendor_path) else { report.errors.push(format!("invalid vendor entry: {}", vendor_path.display())); continue; };
                    let cargo = vendor_path.join(BUNDLE_SOURCE_REQUIRED_FILES[0]);
                    let checksum = vendor_path.join(BUNDLE_VENDOR_CHECKSUM_FILE);
                    if !vendor_names.iter().any(|name| name == BUNDLE_SOURCE_REQUIRED_FILES[0]) || !vendor_names.iter().any(|name| name == BUNDLE_VENDOR_CHECKSUM_FILE) || read_regular_text_limited(&cargo, usize::MAX).is_err() || read_regular_text_limited(&checksum, usize::MAX).is_err() { report.errors.push(format!("incomplete vendored crate: {}", vendor_path.display())); }
                }
                continue;
            }
            let package_names = rooted_list_names(&path)?;
            let package_file = path.join(BUNDLE_SOURCE_REQUIRED_FILES[1]);
            let cargo_file = path.join(BUNDLE_SOURCE_REQUIRED_FILES[0]);
            report.source_packages += 1;
            if !package_names.iter().any(|name| name == BUNDLE_SOURCE_REQUIRED_FILES[1]) || read_regular_text_limited(&package_file, usize::MAX).is_err() { report.errors.push(format!("missing or invalid {}/package.spiproj", path.display())); }
            if package_names.iter().any(|name| name == BUNDLE_SOURCE_REQUIRED_FILES[0]) {
                physical_cargo_members.insert(source_name.clone());
                report.cargo_crates += 1;
                report.public_bins += read_regular_text_limited(&cargo_file, usize::MAX)?.match_indices("[[bin]]").count();
            } else {
                report.spiral_only_packages += 1;
                let has_rust = package_names.iter().any(|name| Path::new(name).extension().and_then(|value| value.to_str()) == Some(BUNDLE_SOURCE_EXTENSIONS[0]));
                if has_rust { report.errors.push(format!("Spiral-only package contains Rust source: {}", path.display())); }
            }
            let mut lines = 0usize;
            walk_crate(&path, &mut lines, &mut report)?;
            let name = path.file_name().and_then(|value| value.to_str()).unwrap_or("crate").to_owned();
            report.crate_lines.push((name.clone(), lines));
            if lines > BUNDLE_CRATE_LINE_LIMIT { report.errors.push(format!("crate line budget exceeded: {name} has {lines}")); }
        }
        let workspace_manifest = read_regular_text_limited(&src.join(BUNDLE_SOURCE_REQUIRED_FILES[0]), usize::MAX)?;
        match workspace_members_from_manifest(&workspace_manifest) {
            Ok(workspace_members) => {
                let bijective = i32::from(workspace_members == physical_cargo_members);
                if eoie_bundle_manifest_mapping_binding(1, bijective) != 1 {
                    let missing = workspace_members.difference(&physical_cargo_members).cloned().collect::<Vec<_>>();
                    let undeclared = physical_cargo_members.difference(&workspace_members).cloned().collect::<Vec<_>>();
                    report.errors.push(format!("workspace member mapping mismatch: missing_physical={missing:?} undeclared_physical={undeclared:?}"));
                }
            }
            Err(error) => {
                let _ = eoie_bundle_manifest_mapping_binding(0, 0);
                report.errors.push(format!("workspace member mapping: {error}"));
            }
        }
    }
    if report.public_bins != BUNDLE_PUBLIC_BINARY_COUNT { report.errors.push(format!("expected {BUNDLE_PUBLIC_BINARY_COUNT} public binary, found {}", report.public_bins)); }
    if !rooted_open_regular_read(&root.join(BUNDLE_ROOT_ENTRIES[0])).is_ok() { report.errors.push("root eoie binary is missing".to_owned()); }
    Ok(report)
}

fn print_report(report: &BundleReport) { for (name, lines) in &report.crate_lines { println!("crate {name} lines={lines}"); } println!("state files={} count_policy=unbounded", report.state_files); for error in &report.errors { eprintln!("bundle error: {error}"); } }

fn verify_flat_zip(archive: &Path) -> Result<usize, String> {
    let entries = zip_entries(archive)?;
    let manifest = manifest_from_archive_entries(&entries)?;
    let binary_evidence_mask = i32::from(entries.iter().any(|entry| entry == BUNDLE_ROOT_ENTRIES[0])) | (i32::from(entries.iter().any(|entry| entry.starts_with(BUNDLE_ARCHIVE_DIRECTORY_ROOTS[0]))) << 1); let source_state_mask = i32::from(entries.iter().any(|entry| entry.starts_with(BUNDLE_ARCHIVE_DIRECTORY_ROOTS[1]))) | (i32::from(entries.iter().any(|entry| entry.starts_with(BUNDLE_ARCHIVE_DIRECTORY_ROOTS[2]))) << 1); if eoie_bundle_archive_root_shape_binding(binary_evidence_mask, source_state_mask) != 1 { return Err("zip is wrapped or missing required eoie/evidence/src/state roots".to_owned()); }
    Ok(usize::try_from(eoie_bundle_payload_count_binding(i32::try_from(manifest.len()).unwrap_or(i32::MAX), 0)).unwrap_or(0))
}

fn flat_verification_receipt(count: usize, bytes: u64, max_bytes: u64) -> Result<(), String> {
    let size_valid = eoie_flat_bundle_size_binding(i32::from(max_bytes > 0), i32::from(bytes <= max_bytes));
    let manifest_valid = eoie_flat_bundle_manifest_binding(i32::from(count > 0), 1);
    if size_valid != 1 { return Err(format!("flat archive size rejected: bytes={bytes} limit={max_bytes}")); }
    if manifest_valid != 1 { return Err("flat archive manifest rejected".to_owned()); }
    if eoie_flat_bundle_complete_binding(manifest_valid, size_valid) != 1 { return Err("flat archive completion rejected".to_owned()); }
    Ok(())
}

fn extract_flat_archive(archive: &Path, destination: &Path) -> Result<usize, String> {
    Ok(archive_extract_with_limit(archive, destination, BUNDLE_EXTRACT_MAX_BYTES)?.1)
}

fn dispatch(args: &[String]) -> Result<(), String> {
    match arg(args, 0, "subcommand")? {
        "growth-baseline" => {
            let predecessor = Path::new(arg(args, 1, "predecessor.zip")?); let previous = Path::new(arg(args, 2, "previous-root")?); let root = Path::new(arg(args, 3, "root")?); owner_growth_seed(predecessor, previous, root)
        }
        "growth-receipt" => {
            let root = Path::new(arg(args, 1, "root")?); let reason = arg(args, 2, "reason")?; let reference = arg(args, 3, "reference")?; owner_growth_author(root, reason, reference)
        }
        "check" => {
            let root = Path::new(arg(args, 1, "root")?);
            let profile = resolve_bundle_profile(args.get(2).map(String::as_str), root)?;
            let before = collect_bundle_manifest(root)?;
            let report = if profile == 2 { check_bundle(root)? } else { check_generic_bundle(root)? };
            let after = collect_bundle_manifest(root)?;
            let count_equal = i32::from(before.len() == after.len());
            let fingerprint_equal = i32::from(manifest_fingerprint(&before) == manifest_fingerprint(&after));
            if eoie_bundle_manifest_parity_binding(count_equal, fingerprint_equal) != 1 { return Err("bundle check manifest parity rejected".to_owned()); }
            verify_manifest_parity(&before, &after)?;
            print_report(&report);
            if !report.errors.is_empty() { return Err(format!("bundle contract failed with {} errors", report.errors.len())); }
            println!("eoie bundle check ok profile={} public_binaries={} manifest_fingerprint={:016x}", if profile == 2 { "eoie" } else { "generic" }, report.public_bins, manifest_fingerprint(&after));
            Ok(())
        }
        "create" => {
            let root = rooted_canonical_directory(Path::new(arg(args, 1, "root")?))?;
            let output_arg = Path::new(arg(args, 2, "output.zip")?);
            let output = if output_arg.is_absolute() { output_arg.to_path_buf() } else { env::current_dir().map_err(|error| error.to_string())?.join(output_arg) };
            let profile = resolve_bundle_profile(args.get(3).map(String::as_str), &root)?;
            if profile == 2 {
                let hygiene_args = vec!["prune-compiler-sidecars".to_owned(), root.display().to_string()];
                prune_compiler_sidecars(&hygiene_args)?;
                let transient_args = vec!["prune-release-transients".to_owned(), root.display().to_string()];
                prune_release_transients(&transient_args)?;
            }
            let report = if profile == 2 { check_bundle(&root)? } else { check_generic_bundle(&root)? };
            print_report(&report);
            if !report.errors.is_empty() { return Err("bundle contract failed".to_owned()); }
            if eoie_bundle_output_preflight_binding(i32::from(!output.starts_with(&root)), i32::from(!rooted_entry_exists(&output)? || rooted_open_regular_read(&output).is_ok())) != 1 { return Err("zip output must be outside bundle root".to_owned()); }
            remove_bundle_output(&output)?;
            let manifest = collect_bundle_manifest(&root)?;
            write_deterministic_deflate_zip(&root, &output, &manifest)?; let output_bytes = rooted_regular_size(&output)?; if eoie_bundle_output_complete_binding(i32::from(!output.starts_with(&root)), i32::from(output_bytes > 0)) != 1 { remove_bundle_output(&output)?; return Err(output.display().to_string()); }
            let count = if profile == 2 { verify_flat_zip(&output)? } else { verify_generic_flat_zip(&output, BUNDLE_ARCHIVE_MAX_BYTES)?.0 };
            verify_archive_parity(&output, &manifest)?;
            let expected_entries = i32::try_from(manifest.len()).unwrap_or(i32::MAX);
            let observed_entries = i32::try_from(count).unwrap_or(i32::MAX);
            if eoie_bundle_entry_binding(expected_entries, observed_entries) != 1 { return Err(format!("typed archive entry mismatch: collected={} archive={count}", manifest.len())); }
            let bytes = output_bytes;
            if eoie_bundle_size_binding(BUNDLE_ARCHIVE_MAX_BYTES as i32, i32::try_from(bytes).unwrap_or(i32::MAX)) != 1 { remove_bundle_output(&output)?; return Err(format!("bundle exceeds typed size limit: {bytes}")); }
            let fingerprint = manifest_fingerprint(&manifest);
            println!("eoie bundle create ok profile={} entries={count} bytes={bytes} manifest_fingerprint={fingerprint:016x} output={}", if profile == 2 { "eoie" } else { "generic" }, output.display());
            Ok(())
        }
        "create-flat" => {
            let root = rooted_canonical_directory(Path::new(arg(args, 1, "root")?))?;
            let output_arg = Path::new(arg(args, 2, "output.zip")?);
            let output = if output_arg.is_absolute() { output_arg.to_path_buf() } else { env::current_dir().map_err(|error| error.to_string())?.join(output_arg) };
            let max_bytes = parsed_max_bytes(arg(args, 3, "max-bytes")?)?;
            if eoie_flat_bundle_preflight_binding(i32::from(rooted_list_names(&root).is_ok()), i32::from(!output.starts_with(&root))) != 1 {
                return Err("flat bundle preflight rejected".to_owned());
            }
            remove_bundle_output(&output)?;
            let manifest = collect_bundle_manifest(&root)?;
            if eoie_flat_bundle_manifest_binding(i32::from(!manifest.is_empty()), 1) != 1 {
                return Err("flat bundle manifest rejected".to_owned());
            }
            let result = (|| -> Result<(usize, u64), String> {
                if eoie_flat_bundle_compression_binding(1, 1) != 1 { return Err("flat bundle compression policy rejected".to_owned()); }
                write_deterministic_deflate_zip(&root, &output, &manifest)?;
                let (count, bytes) = verify_generic_flat_zip(&output, max_bytes)?;
                flat_verification_receipt(count, bytes, max_bytes)?;
                verify_archive_parity(&output, &manifest)?;
                Ok((count, bytes))
            })();
            let (count, bytes) = match result {
                Ok(value) => value,
                Err(error) => { remove_bundle_output(&output)?; return Err(error); }
            };
            println!("eoie bundle create-flat ok entries={count} bytes={bytes} manifest_fingerprint={:016x} output={}", manifest_fingerprint(&manifest), output.display());
            Ok(())
        }
        "verify-flat" => {
            let archive = Path::new(arg(args, 1, "archive.zip")?);
            let max_bytes = parsed_max_bytes(arg(args, 2, "max-bytes")?)?;
            let (count, bytes) = verify_generic_flat_zip(archive, max_bytes)?;
            flat_verification_receipt(count, bytes, max_bytes)?;
            println!("eoie bundle verify-flat ok entries={count} bytes={bytes} limit={max_bytes}");
            Ok(())
        }
        "verify" => {
            let archive = Path::new(arg(args, 1, "archive.zip")?);
            let bytes = rooted_regular_size(archive)?;
            if eoie_bundle_verify_preflight_binding(1, i32::from(bytes > 0)) != 1 { return Err("bundle verify preflight rejected".to_owned()); }
            let profile = resolve_bundle_archive_profile(args.get(2).map(String::as_str), archive)?;
            let count = if profile == 2 { verify_flat_zip(archive)? } else { verify_generic_flat_zip(archive, BUNDLE_ARCHIVE_MAX_BYTES)?.0 };
            let size_ok = eoie_bundle_size_binding(BUNDLE_ARCHIVE_MAX_BYTES as i32, i32::try_from(bytes).unwrap_or(i32::MAX));
            if size_ok != 1 { return Err(format!("bundle exceeds typed size limit: {bytes}")); }
            if eoie_bundle_verify_complete_binding(i32::from(count > 0), size_ok) != 1 { return Err("bundle verify completion rejected".to_owned()); }
            println!("eoie bundle verify ok profile={} entries={count} bytes={bytes}", if profile == 2 { "eoie" } else { "generic" });
            Ok(())
        }
        "rehydrate" => {
            let archive = Path::new(arg(args, 1, "archive.zip")?);
            let destination = Path::new(arg(args, 2, "destination")?);
            let destination_absent = i32::from(!rooted_entry_exists(destination)?);
            let verified_entries = verify_generic_flat_zip(archive, BUNDLE_ARCHIVE_MAX_BYTES)?.0;
            let preflight_ok = eoie_bundle_rehydrate_preflight_binding(i32::from(verified_entries > 0), destination_absent);
            let archive_preflight_ok = eoie_archive_extract_preflight_binding(i32::from(destination_absent == 0), i32::from(verified_entries > 0));
            if preflight_ok != 1 || archive_preflight_ok != 1 { return Err("typed rehydration preflight rejected".to_owned()); }
            let extracted_entries = extract_flat_archive(archive, destination)?;
            let archive_complete_ok = eoie_archive_extract_complete_binding(i32::try_from(verified_entries).unwrap_or(i32::MAX), i32::try_from(extracted_entries).unwrap_or(i32::MAX));
            let archive_process_ok = eoie_archive_extract_process_binding(1, i32::from(rooted_list_names(destination).is_ok()));
            let archive_receipt_ok = eoie_archive_extract_receipt_binding(archive_preflight_ok, eoie_bundle_complete_binding(archive_process_ok, archive_complete_ok));
            let extract_ok = eoie_bundle_rehydrate_extract_binding(i32::from(archive_complete_ok == 1), i32::from(rooted_list_names(destination).is_ok()));
            if extract_ok != 1 || archive_receipt_ok != 1 { rollback_rehydrate_destination(destination)?; return Err("typed rehydration extraction rejected".to_owned()); }
            let profile = resolve_bundle_profile(args.get(3).map(String::as_str), destination)?;
            let report = if profile == 2 { check_bundle(destination)? } else { check_generic_bundle(destination)? };
            print_report(&report);
            let structure_mask = i32::from(bundle_profile_signature(destination) == 1) | (i32::from(rooted_open_regular_read(&destination.join(BUNDLE_EOIE_AGILE_PATH)).is_ok()) << 1) | (i32::from(!collect_bundle_manifest(destination)?.is_empty()) << 2);
            let structure_ok = eoie_bundle_rehydrate_structure_binding(profile, structure_mask) == 1;
            let validate_ok = eoie_bundle_rehydrate_validate_binding(i32::from(report.errors.is_empty()), i32::from(structure_ok));
            if validate_ok != 1 { rollback_rehydrate_destination(destination)?; return Err(format!("rehydrated {} bundle validation rejected", if profile == 2 { "eoie" } else { "generic" })); }
            let preflight_extract_ok = eoie_bundle_complete_binding(preflight_ok, extract_ok);
            if eoie_bundle_rehydrate_receipt_binding(preflight_extract_ok, validate_ok) != 1 { rollback_rehydrate_destination(destination)?; return Err("typed rehydration receipt incomplete".to_owned()); }
            println!("eoie bundle rehydrate ok profile={} entries={extracted_entries} destination={} receipt=typed", if profile == 2 { "eoie" } else { "generic" }, destination.display());
            Ok(())
        }
        _ => Err("bundle supports growth-baseline, growth-receipt, check, create, create-flat, verify, verify-flat, rehydrate".to_owned()),
    }
}

#[must_use]
